// AT-05 parity harness for the ATP Workshop.
//
// This script is the durable, committed version of the parity check
// defined in docs/workshop/scenario-contract-v1.md (see the "Parity
// definition" section of that contract). It runs the JavaScript engine
// in workshop/js/ and compares its structured output, field by field,
// against the golden fixtures generated by the Python reference engine.
//
// Run it from the repository root:
//
//   node workshop/tests/parity.js
//
// Exit code is 0 only when every fixture matches. Any mismatch, missing
// fixture, or engine error exits nonzero. On failure, fix the engine,
// never the fixture: fixtures are generated by the reference exporter
// and are never hand-edited (see the contract's versioning rule).

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { SCENARIO_NAMES, runScenario } from "../js/fixture.js";

// Paths are resolved from this file's location, not the caller's
// working directory, so the harness behaves the same from anywhere.
// This file lives at workshop/tests/parity.js, so the repository root
// is two directories up.
const testsDir = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(testsDir, "..", "..");
const fixturesDir = join(repoRoot, "docs", "workshop", "fixtures");
const indexPath = join(fixturesDir, "index.json");
const reportPath = join(testsDir, "parity-report.txt");

// How many diffs to print per failing fixture. The first several are
// enough to locate the problem; a long dump hides the signal.
const MAX_DIFFS_PER_FIXTURE = 10;

// Longest rendering of a single value in a diff line.
const MAX_VALUE_LENGTH = 200;

// Render a value for a diff line: JSON text, truncated if very long.
// JSON rendering keeps strings visibly quoted and null visibly null,
// so a string that looks like a number is never confused with one.
function renderValue(value) {
  if (value === undefined) return "undefined";
  let text;
  try {
    text = JSON.stringify(value);
  } catch {
    text = String(value);
  }
  if (text === undefined) text = String(value);
  if (text.length > MAX_VALUE_LENGTH) {
    text = text.slice(0, MAX_VALUE_LENGTH) + "... [truncated]";
  }
  return text;
}

// A plain value category, used to keep the comparison honest: a number
// is never equal to a string, an array is never equal to an object,
// and null is its own category, equal only to null.
function categoryOf(value) {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  return typeof value; // "string", "number", "boolean", "object", "undefined"
}

// Deep-compare the engine object against the fixture object using
// exactly the contract projection:
//   strings byte for byte (strict equality)
//   numbers exact
//   booleans exact
//   null equal only to null
//   arrays: same length, same order, element by element
//   objects: structural equality, key order ignored
// Every field present in the fixture is compared. A field present in
// the engine object but missing from the fixture is also a diff, at
// any depth. Differences are appended to diffs as
// { path, fixtureValue, engineValue }.
function compareValues(fixtureValue, engineValue, path, diffs) {
  const fixtureCategory = categoryOf(fixtureValue);
  const engineCategory = categoryOf(engineValue);

  if (fixtureCategory !== engineCategory) {
    diffs.push({ path: path, fixtureValue: fixtureValue, engineValue: engineValue });
    return;
  }

  if (fixtureCategory === "array") {
    if (fixtureValue.length !== engineValue.length) {
      diffs.push({
        path: path + ".length",
        fixtureValue: fixtureValue.length,
        engineValue: engineValue.length,
      });
    }
    const shared = Math.min(fixtureValue.length, engineValue.length);
    for (let i = 0; i < shared; i += 1) {
      compareValues(fixtureValue[i], engineValue[i], path + "[" + i + "]", diffs);
    }
    return;
  }

  if (fixtureCategory === "object") {
    // Every fixture field must be present in the engine object and equal.
    for (const key of Object.keys(fixtureValue)) {
      const childPath = path === "" ? key : path + "." + key;
      if (!Object.prototype.hasOwnProperty.call(engineValue, key)) {
        diffs.push({ path: childPath, fixtureValue: fixtureValue[key], engineValue: undefined });
      } else {
        compareValues(fixtureValue[key], engineValue[key], childPath, diffs);
      }
    }
    // Extra engine fields the fixture lacks are diffs too.
    for (const key of Object.keys(engineValue)) {
      if (!Object.prototype.hasOwnProperty.call(fixtureValue, key)) {
        const childPath = path === "" ? key : path + "." + key;
        diffs.push({ path: childPath, fixtureValue: undefined, engineValue: engineValue[key] });
      }
    }
    return;
  }

  // Scalars (string, number, boolean, null): strict equality covers
  // all of the contract rules for these, including null only to null.
  if (fixtureValue !== engineValue) {
    diffs.push({ path: path, fixtureValue: fixtureValue, engineValue: engineValue });
  }
}

// Check the contract's seq rule on the engine's full ledger records
// for one run. The fixture carries field names only, so this check
// runs on the records returned by runScenario: the seq values must be
// integers forming a contiguous sequence in order, each exactly one
// more than the previous. Problems are appended as diffs. These are
// rule checks rather than fixture comparisons, so they carry
// pre-rendered fixtureText and engineText: the rule on the fixture
// side, the observed value on the engine side.
function checkSeqRule(records, diffs) {
  if (!Array.isArray(records)) {
    diffs.push({
      path: "records",
      fixtureText: "an array of ledger records (contract seq rule)",
      engineText: renderValue(records),
    });
    return;
  }
  for (let i = 0; i < records.length; i += 1) {
    const seq = records[i] === null || records[i] === undefined ? undefined : records[i].seq;
    if (!Number.isInteger(seq)) {
      diffs.push({
        path: "records[" + i + "].seq",
        fixtureText: "an integer (contract seq rule)",
        engineText: renderValue(seq),
      });
      // Without an integer here, contiguity cannot be judged further.
      continue;
    }
    if (i > 0) {
      const previous = records[i - 1] === null || records[i - 1] === undefined ? undefined : records[i - 1].seq;
      if (Number.isInteger(previous) && seq !== previous + 1) {
        diffs.push({
          path: "records[" + i + "].seq",
          fixtureText: "previous seq plus one, " + (previous + 1) + " (contract seq rule)",
          engineText: renderValue(seq),
        });
      }
    }
  }
}

// Run one index entry end to end. Returns { passed, diffs } where
// diffs is empty only when everything about the run matched.
function checkFixture(entry, index) {
  const diffs = [];
  const scenario = entry.scenario;
  const seed = entry.seed;

  // The entry must belong to the scenario and seed lists the index
  // itself declares. This guards the index, not the engine.
  if (Array.isArray(index.scenarios) && !index.scenarios.includes(scenario)) {
    diffs.push({
      path: "index.scenarios",
      fixtureText: "index entry scenario " + renderValue(scenario),
      engineText: "index declares scenarios " + renderValue(index.scenarios),
    });
  }
  if (Array.isArray(index.seeds) && !index.seeds.includes(seed)) {
    diffs.push({
      path: "index.seeds",
      fixtureText: "index entry seed " + renderValue(seed),
      engineText: "index declares seeds " + renderValue(index.seeds),
    });
  }
  if (!SCENARIO_NAMES.includes(scenario)) {
    diffs.push({ path: "scenario", fixtureValue: scenario, engineValue: "not a scenario the engine knows" });
    return { passed: false, diffs: diffs };
  }

  // Load the fixture file. A missing or unreadable fixture is a
  // failure for this entry, not a reason to stop the whole run.
  let fixture;
  try {
    fixture = JSON.parse(readFileSync(join(fixturesDir, entry.file), "utf8"));
  } catch (error) {
    diffs.push({
      path: entry.file,
      fixtureText: "a readable JSON fixture file",
      engineText: renderValue(String(error && error.message ? error.message : error)),
    });
    return { passed: false, diffs: diffs };
  }

  // The fixture itself must carry the contract version the index
  // names, and its recorded verdict must be PASS.
  if (fixture.contract_version !== index.contract_version) {
    diffs.push({
      path: "contract_version (fixture file vs index)",
      fixtureText: renderValue(fixture.contract_version),
      engineText: "index declares " + renderValue(index.contract_version),
    });
  }
  if (fixture.verdict !== "PASS") {
    diffs.push({
      path: "verdict (fixture file)",
      fixtureText: renderValue(fixture.verdict),
      engineText: "required " + renderValue("PASS"),
    });
  }

  // Run the engine. An engine error is a failure for this entry.
  let result;
  try {
    result = runScenario(scenario, seed);
  } catch (error) {
    diffs.push({
      path: "runScenario",
      fixtureText: "a completed run",
      engineText: renderValue(String(error && error.message ? error.message : error)),
    });
    return { passed: false, diffs: diffs };
  }
  if (!result || typeof result !== "object" || !result.fixture || typeof result.fixture !== "object") {
    diffs.push({ path: "runScenario result", fixtureValue: "an object with a fixture object", engineValue: result });
    return { passed: false, diffs: diffs };
  }

  // The engine run's own verdict must be PASS, even if it happened to
  // match a fixture that said otherwise (already flagged above).
  if (result.fixture.verdict !== "PASS") {
    diffs.push({
      path: "verdict (engine run)",
      fixtureText: "required " + renderValue("PASS"),
      engineText: renderValue(result.fixture.verdict),
    });
  }

  // The main event: the full fixture projection, field by field.
  compareValues(fixture, result.fixture, "", diffs);

  // The additional seq rule, checked on the engine's records.
  checkSeqRule(result.records, diffs);

  return { passed: diffs.length === 0, diffs: diffs };
}

function main() {
  const lines = [];
  let contractVersion = "unknown";
  let total = 0;
  let passedCount = 0;
  let fatalError = null;

  lines.push("AT-05 parity harness");
  lines.push("Contract source: docs/workshop/scenario-contract-v1.md, Parity definition");

  let index = null;
  try {
    index = JSON.parse(readFileSync(indexPath, "utf8"));
  } catch (error) {
    fatalError = "could not read or parse " + indexPath + ": " + String(error && error.message ? error.message : error);
  }

  if (index !== null) {
    // The scenario list, the seed list, and the contract version all
    // come from the index. Nothing about the fixture set is hardcoded
    // here: entries are enumerated from index.fixtures, in order.
    contractVersion = index.contract_version;
    const scenarios = Array.isArray(index.scenarios) ? index.scenarios : [];
    const seeds = Array.isArray(index.seeds) ? index.seeds : [];
    const entries = Array.isArray(index.fixtures) ? index.fixtures : [];

    lines.push("Contract version: " + contractVersion + " (from docs/workshop/fixtures/index.json)");
    lines.push("Scenarios from index: " + scenarios.join(", "));
    lines.push("Seeds from index: " + seeds.join(", "));
    lines.push("Fixtures enumerated from index: " + entries.length);
    lines.push("");

    if (!Array.isArray(index.fixtures)) {
      fatalError = "index.json has no fixtures array to enumerate";
    } else {
      for (const entry of entries) {
        total += 1;
        const label = entry.scenario + " seed " + entry.seed + " (" + entry.file + ")";
        let outcome;
        try {
          outcome = checkFixture(entry, index);
        } catch (error) {
          // A harness level surprise is still just a failed entry:
          // report it, keep going, and exit nonzero at the end.
          outcome = {
            passed: false,
            diffs: [{ path: "harness", fixtureValue: "a completed check", engineValue: String(error && error.message ? error.message : error) }],
          };
        }
        if (outcome.passed) {
          passedCount += 1;
          lines.push("PASS " + label);
        } else {
          lines.push("FAIL " + label);
          const shown = outcome.diffs.slice(0, MAX_DIFFS_PER_FIXTURE);
          for (let i = 0; i < shown.length; i += 1) {
            const diff = shown[i];
            // Comparison diffs carry raw values, rendered here. Rule
            // check diffs carry pre-rendered text instead (see
            // checkSeqRule and the verdict checks in checkFixture).
            const fixtureText = diff.fixtureText !== undefined ? diff.fixtureText : renderValue(diff.fixtureValue);
            const engineText = diff.engineText !== undefined ? diff.engineText : renderValue(diff.engineValue);
            lines.push(
              "  diff " + (i + 1) + ": " + diff.path +
              ": fixture=" + fixtureText +
              " engine=" + engineText
            );
          }
          if (outcome.diffs.length > shown.length) {
            lines.push("  ... and " + (outcome.diffs.length - shown.length) + " more diffs (only the first " + MAX_DIFFS_PER_FIXTURE + " are shown)");
          }
        }
      }
    }
  }

  if (fatalError !== null) {
    lines.push("FAIL harness: " + fatalError);
  }

  lines.push("");
  lines.push("Parity: " + passedCount + "/" + total + " against " + contractVersion);

  const report = lines.join("\n") + "\n";

  // Print the report, and write the same full report to disk. The
  // file is regenerated on every run, pass or fail.
  process.stdout.write(report);
  try {
    writeFileSync(reportPath, report, "utf8");
  } catch (error) {
    process.stderr.write("Could not write report file " + reportPath + ": " + String(error && error.message ? error.message : error) + "\n");
    process.exitCode = 1;
    return;
  }

  const allPassed = fatalError === null && total > 0 && passedCount === total;
  process.exitCode = allPassed ? 0 : 1;
}

main();
